<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\Request;use App\Core\Response;use App\Services\PersonnelService;
class PersonnelController {public function index():void{Response::json((new PersonnelService())->all($_GET));}public function show():void{$r=(new PersonnelService())->one((int)Request::param('id',0));if(!$r)Response::json(['message'=>'Personnel introuvable'],404);Response::json($r);}public function store():void{$r=(new PersonnelService())->create(Request::json());if(isset($r['error']))Response::json(['message'=>$r['error']],422);Response::json($r,201);}public function update():void{$r=(new PersonnelService())->update((int)Request::param('id',0),Request::json());if(isset($r['error']))Response::json(['message'=>$r['error']],422);Response::json($r);}public function status():void{$r=(new PersonnelService())->status((int)Request::param('id',0),(string)(Request::json()['status']??''));if(isset($r['error']))Response::json(['message'=>$r['error']],422);Response::json($r);}public function nextNumber():void{Response::json((new PersonnelService())->nextNumber());}}
